import time
import subprocess
from ta_ue_plugin_ultracaller.uc_test_types.uc_ue_iperf_ep import UcUeEndpoint
from ute_ue.data_transfers.iperf import publisher
from .uc_data_transfer_base import UcDataTransferBase
from ute_ue.data_transfers.iperf_data_transfer import IperfDataTransfer


class UcIperf(UcDataTransferBase):

    def __init__(self, name, dt_definition, configuration, uc_connection, logger_name='ute_ue', test_name=None):
        """
        :param name:
        :param dt_definition:
        :param configuration:
        :param uc_connection:
        :param logger_name:
        :param test_name:
        """
        self.protocol_details = dt_definition.protocol_details
        self._validate_protocol_details(dt_definition)
        dt_definition = self._fix_dt_definition(dt_definition)
        configuration = self._fix_config(configuration)
        super(UcIperf, self).__init__(name=name, dt_definition=dt_definition, configuration=configuration,
                                      uc_connection=uc_connection, logger_name=logger_name, test_name=test_name)
        self.iperf = IperfDataTransfer(name=name, dt_definition=dt_definition, configuration=configuration,
                                       logger_name=logger_name)
        self.iperf.ue_endpoint = UcUeEndpoint(uc_dt_base=self, uc_connection=uc_connection, ue_ip=self.iperf.ue_ip)
        self._uc_connection = uc_connection
        self.appsvr_iperf = None

    def get_average_throughput(self, omit=0):
        """
        Returns average throughput in Kbits/sec

        :param omit: it is a delay in seconds to start counting the tput ex. '20' - 1st 20 seconds of datatransfer will be omitted.
        :return: value of Average throughput in unit: Kbits/sec
        """
        return self.iperf.get_average_throughput(omit=omit)

    def get_data_transfer_statistics(self):
        """:return: Statistics if test has finished succesfully else none"""
        return self.iperf.get_data_transfer_statistics()

    def start(self):
        """Starts test and deletes it if something goes wrong."""
        try:
            self._start()
        except Exception as e:  # We want to raise exception if something goes wrong and the test needs to be deleted.
            self._uc_connection.delete_test(test_name=self.test_name)
            raise e

    def _start(self):
        """
        Start data transfer with parameters defined in dt_definition passed during initialization.

        :return: None
        """
        self.iperf.server_endpoint.prepare_host_device()
        self.iperf.client_endpoint.prepare_host_device()
        self.iperf.iperf_server = self.iperf.server_endpoint.get_server_command_object(
            self.iperf.client_endpoint.endpoint_ip)
        self.iperf.iperf_client = self.iperf.client_endpoint.get_client_command_object(
            self.iperf.server_endpoint.endpoint_ip)
        self._build_publisher()

        self.iperf.iperf_server.start(timeout=self.iperf.duration + 30)  # start server in background
        time.sleep(1)  # give server chance to start
        self.iperf.iperf_client.start(timeout=self.iperf.duration + 30)  # start client in background
        time.sleep(1)

    def stop(self):
        """:return: Stops the test in both appserver and ue"""
        self.iperf.stop()

    def _build_publisher(self):
        """
        Build IperfPublisher.

        Should be called after creation of self.iperf_client and self.iperf_server
        """
        self.iperf._publisher = publisher.IperfPublisher(iperf_direction=self.direction,
                                                         port=self.iperf.port,
                                                         ue_ip=self.iperf.ue_ip,
                                                         app_server_ip=self.iperf.app_server_ip,
                                                         iperf_client=self.iperf.iperf_client,
                                                         iperf_server=self.iperf.iperf_server,
                                                         logger=self.logger)

    def _fix_config(self, configuration):
        configuration['ue_ip'] = self.protocol_details['ue_ip']

        # If app_server is not chosen in the protocol_details the first server in configuration is chosen
        if self.protocol_details.get('app_server'):
            app_server = self.protocol_details['app_server']
            configuration['ue_host'] = configuration['APP_SERVERS'][app_server]['host']
        else:
            app_server = list(configuration['APP_SERVERS'].keys())[0]
            configuration['ue_host'] = configuration['APP_SERVERS'][app_server]['host']

        # If appserver is in localhost and bindinterface is not defined iperf will use 127.0.0.1 which does not work.
        # VM's ip is searched and set in bindinterface to fix this.
        if not configuration['APP_SERVERS'][app_server].get('bind_interface_ip') and \
                (configuration['ue_host']['host'] == 'localhost' or configuration['ue_host']['host'] == '127.0.0.1'):
            configuration['APP_SERVERS'][app_server]['bind_interface_ip'] = self._localhost_ip
        return configuration

    def _fix_dt_definition(self, dt_definition):
        if self.protocol_details.get('dl_throughput'):
            dt_definition.dl_throughput = self.protocol_details.get('dl_throughput')
        if self.protocol_details.get('ul_throughput'):
            dt_definition.ul_throughput = self.protocol_details.get('ul_throughput')
        return dt_definition

    def _validate_protocol_details(self, dt_definition):
        err_msg = ''
        if not self.protocol_details.get('ue_ip'):
            err_msg = 'No ue_ip in protocol_details'
        if dt_definition.direction == 'simultaneous_ul_dl':
            err_msg += '\r\n Direction simultaneous_ul_dl is not supported'
        if err_msg:
            raise ValueError(err_msg)

    @property
    def imei(self):
        """:return: Ue's imei"""
        return self._imei

    @property
    def protocol(self):
        """:return: Either udp or tcp"""
        return self._dt_definition.protocol

    @property
    def running(self):
        """:return: True if running"""
        return self._running

    @property
    def test_id(self):
        """:return: ID of the uc test"""
        return self._test_id

    @property
    def ue_options(self):
        """:return: Iperf options for ue"""
        if self.iperf.direction == 'dl':
            return self.iperf.cmd_options.server_options(self._app_svr_ip, self.iperf.ue_endpoint.endpoint_ip)
        return self.iperf.cmd_options.client_options(self.iperf.ue_endpoint.endpoint_ip, self._app_svr_ip)

    @property
    def _app_svr_ip(self):
        if self._is_localhost:
            return self._localhost_ip
        return self.iperf.appsvr_endpoint.endpoint_ip

    @property
    def _is_localhost(self):
        if self.iperf.appsvr_endpoint.host_device.__class__.__name__ == 'UnixLocal':
            return True
        return False

    @property
    def _localhost_ip(self):
        # Tests are run on virtual machines that always have an eth0 interface
        output = subprocess.check_output('ip address show dev eth0', shell=True).decode('utf-8')
        for row in output.split('\n'):
            output_list = row.split(' ')
            if 'inet' in output_list:
                ip = output_list[output_list.index('inet') + 1].split('/')[0]
                return ip

    @property
    def ue_report_key(self):
        """:return: Key for report in report dictionary"""
        return self.iperf.app_server_ip, '{}@{}'.format(self.iperf.port, self.iperf.ue_ip)

    @property
    def ue_stats_key(self):
        """:return: Key for interval statistics in report dictionary"""
        return '@{}'.format(self.iperf.app_server_ip), '{}@{}'.format(self.iperf.port, self.iperf.ue_ip)

    # Only UcUeEndpoint should use these below
    def start_and_wait(self):
        """Starts the test and blocks until test is running"""
        self._start_and_wait_for_running()

    def stop_and_wait(self):
        """Stops the test and blocks until test is completed"""
        self._stop_and_wait_for_completed()
